(() => {
  const canvas = document.querySelector('#arena');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const ui = { start: $('#startScreen'), result: $('#resultScreen'), resultTitle: $('#resultTitle'), resultText: $('#resultText'), startButton: $('#startButton'), rematch: $('#rematchButton'), timer: $('#timer'), round: $('#roundLabel'), banner: $('#roundBanner'), pHealth: $('#playerHealth'), eHealth: $('#enemyHealth'), pMeter: $('#playerMeter'), eMeter: $('#enemyMeter'), combo: $('#comboReadout'), comboCount: $('#comboCount'), pips: $('#roundPips') };
  const input = { left:false, right:false, jump:false, punch:false, kick:false, heavy:false, guard:false };
  const keyMap = { ArrowLeft:'left', KeyA:'left', ArrowRight:'right', KeyD:'right', ArrowUp:'jump', KeyW:'jump', KeyZ:'punch', KeyJ:'punch', KeyX:'kick', KeyK:'kick', KeyC:'heavy', KeyL:'heavy', ShiftLeft:'guard', ShiftRight:'guard', KeyS:'guard', Space:'jump' };
  const attacks = { punch:{name:'JAB',damage:7,range:92,duration:.34,start:.10,end:.22,stun:.25,power:10,color:'#d8ff43'}, kick:{name:'ROUNDHOUSE',damage:11,range:115,duration:.48,start:.17,end:.31,stun:.38,power:15,color:'#ffb55b'}, heavy:{name:'RIFT BREAKER',damage:17,range:130,duration:.68,start:.28,end:.44,stun:.58,power:24,color:'#ff5e48'} };
  const game = { live:false, over:false, time:60, round:1, playerWins:0, enemyWins:0, last:0, accumulator:0, width:0, height:0, floor:0, shake:0, particles:[], sparks:[], ambient:[], combo:0, comboTimer:0, sound:false, audio:null };
  const makeFighter = (x, isPlayer) => ({ x, y:0, vx:0, vy:0, face:isPlayer?1:-1, grounded:true, health:100, meter:0, wins:0, isPlayer, attack:null, attackCooldown:0, stun:0, guard:false, flash:0, pose:0, aiThink:0, aiAction:'', aiWait:0, hitThisAttack:false, lastAttack:'' });
  let player = makeFighter(0,false), enemy = makeFighter(0,false);
  function resize(){ const r=canvas.getBoundingClientRect();const d=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);game.width=r.width;game.height=r.height;game.floor=r.height*(r.width<700?.70:.77);if(game.ambient.length===0)for(let i=0;i<38;i++)game.ambient.push({x:Math.random(),y:Math.random(),s:Math.random()*2+0.5,a:Math.random()*.4+.08,v:Math.random()*.07+.025}); }
  window.addEventListener('resize',resize,{passive:true});resize();
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function audioTone(freq=180,duration=.08,type='sawtooth',gain=.04){if(!game.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!game.audio)game.audio=new AC();if(game.audio.state==='suspended')game.audio.resume();const o=game.audio.createOscillator(),g=game.audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,game.audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,freq*.55),game.audio.currentTime+duration);g.gain.setValueAtTime(gain,game.audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,game.audio.currentTime+duration);o.connect(g);g.connect(game.audio.destination);o.start();o.stop(game.audio.currentTime+duration)}catch(_){}}
  function resetFighters(){const w=game.width;player=makeFighter(w*.34,true);enemy=makeFighter(w*.66,false);player.face=1;enemy.face=-1;player.wins=game.playerWins;enemy.wins=game.enemyWins;game.time=60;game.combo=0;game.comboTimer=0;game.particles=[];game.sparks=[];ui.timer.textContent='60';updateHud()}
  function beginMatch(){game.playerWins=0;game.enemyWins=0;game.round=1;resetFighters();game.over=false;ui.start.hidden=true;ui.result.hidden=true;game.live=true;showBanner('ROUND 01','FIGHT!');}
  function showBanner(label,text){ui.banner.innerHTML=`<span>${label}</span><strong>${text}</strong>`;ui.banner.classList.remove('show');void ui.banner.offsetWidth;ui.banner.classList.add('show')}
  ui.startButton.addEventListener('click',beginMatch);ui.rematch.addEventListener('click',beginMatch);
  function setAction(name,value){if(!(name in input))return;input[name]=value;document.querySelectorAll(`[data-action="${name}"]`).forEach(b=>b.classList.toggle('pressed',value))}
  window.addEventListener('keydown',e=>{const a=keyMap[e.code];if(a){e.preventDefault();setAction(a,true)}if(e.code==='Enter'&&!game.live)beginMatch()});window.addEventListener('keyup',e=>{const a=keyMap[e.code];if(a)setAction(a,false)});window.addEventListener('blur',()=>Object.keys(input).forEach(k=>setAction(k,false)));
  document.querySelectorAll('[data-action]').forEach(button=>{const a=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture?.(e.pointerId);setAction(a,true)});for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,()=>setAction(a,false));});
  $('#soundButton').addEventListener('click',e=>{game.sound=!game.sound;e.currentTarget.innerHTML=`♪ <span>SOUND ${game.sound?'ON':'OFF'}</span>`;if(game.sound)audioTone(420,.09,'triangle',.025)});
  function updateHud(){ui.pHealth.style.width=`${Math.max(0,player.health)}%`;ui.eHealth.style.width=`${Math.max(0,enemy.health)}%`;ui.pMeter.style.width=`${player.meter}%`;ui.eMeter.style.width=`${enemy.meter}%`;ui.round.textContent=`ROUND ${String(game.round).padStart(2,'0')}`;[...ui.pips.children].forEach((p,i)=>{p.classList.toggle('active',i<game.round)})}
  function startAttack(f,type){if(f.attack||f.attackCooldown>0||f.stun>0||f.health<=0)return;const data=attacks[type];f.attack={...data,type,t:0,hit:false};f.hitThisAttack=false;f.lastAttack=type;f.attackCooldown=data.duration*.38;f.pose=0;audioTone(type==='heavy'?105:type==='kick'?155:225,.075,'sawtooth',.018)}
  function jump(f){if(f.grounded&&f.stun<=0&&f.health>0){f.vy=-game.height*.95;f.grounded=false;audioTone(280,.06,'triangle',.015)}}
  function hit(attacker,target,a){if(a.hit)return;const range=a.range*(game.width<700?.87:1);if(Math.abs(target.x-attacker.x)>range+20||!target.grounded&&target.y>game.height*.35)return;if(target.guard&&target.face===-attacker.face&&a.type!=='heavy'){a.hit=true;target.meter=clamp(target.meter+8,0,100);attacker.meter=clamp(attacker.meter+3,0,100);target.stun=.12;for(let i=0;i<5;i++)particle(target.x,target.y-game.height*.22,a.color,1.3);audioTone(300,.06,'triangle',.025);return}a.hit=true;const damage=a.damage*(target.guard?.48:1);target.health=clamp(target.health-damage,0,100);target.stun=a.stun;target.vx=attacker.face*a.power*(game.width/950)*(target.guard?.45:1);target.flash=.13;target.meter=clamp(target.meter+damage*1.1,0,100);attacker.meter=clamp(attacker.meter+damage*.55,0,100);game.shake=Math.max(game.shake,a.type==='heavy'?9:5);for(let i=0;i<(a.type==='heavy'?16:10);i++)particle(target.x-attacker.face*14,target.y-game.height*.28,a.color,1+(i%3)*.65);for(let i=0;i<7;i++)game.sparks.push({x:target.x-attacker.face*10,y:target.y-game.height*.28,vx:(Math.random()-.5)*270,vy:(Math.random()-.7)*250,life:.3,color:a.color});audioTone(a.type==='heavy'?82:125,.15,'square',.045);
    if(attacker.isPlayer){game.combo++;game.comboTimer=1.5;ui.comboCount.textContent=game.combo;ui.combo.classList.add('visible')}else{game.combo=0;ui.combo.classList.remove('visible')}
    if(target.health<=0){target.health=0;target.stun=1.2;target.vx=attacker.face*180;target.vy=-220;target.grounded=false;}
  }
  function particle(x,y,color,power=1){game.particles.push({x,y,vx:(Math.random()-.5)*150*power,vy:(Math.random()-.8)*145*power,life:.3+Math.random()*.35,size:2+Math.random()*4,color})}
  function aiUpdate(dt){if(enemy.stun>0||!game.live)return;const dist=player.x-enemy.x;enemy.face=dist>0?1:-1;enemy.aiThink-=dt;enemy.aiWait-=dt;enemy.guard=enemy.aiAction==='guard'&&enemy.aiWait>0;if(enemy.aiThink<=0){enemy.aiThink=.22+Math.random()*.4;const d=Math.abs(dist),skill=game.round===1?.36:.52;if(d>game.width*.27){enemy.aiAction='approach';enemy.aiWait=.7}else if(player.attack&&d<155&&Math.random()<.30+skill*.2){enemy.aiAction='guard';enemy.aiWait=.24+Math.random()*.28}else if(d<145&&enemy.attackCooldown<=0&&Math.random()<skill){const r=Math.random();enemy.aiAction=r>.81?'heavy':r>.43?'kick':'punch';enemy.aiWait=.1+Math.random()*.2}else if(d<90&&Math.random()<.16){enemy.aiAction='retreat';enemy.aiWait=.28}else{enemy.aiAction='approach';enemy.aiWait=.3}}
    if(enemy.aiWait<=0&&['punch','kick','heavy'].includes(enemy.aiAction)){startAttack(enemy,enemy.aiAction);enemy.aiWait=.45;enemy.aiAction='approach'}
  }
  function updateFighter(f,other,dt){f.face=other.x>f.x?1:-1;f.attackCooldown=Math.max(0,f.attackCooldown-dt);f.stun=Math.max(0,f.stun-dt);f.flash=Math.max(0,f.flash-dt);f.pose+=dt*(f.grounded?7:3);f.guard=f.isPlayer?input.guard:f.guard;
    if(f.attack){f.attack.t+=dt;if(!f.attack.hit&&f.attack.t>=f.attack.start)hit(f,other,f.attack);if(f.attack.t>=f.attack.duration)f.attack=null}
    const scale=game.width/950;let move=0;if(f.isPlayer){move=(input.right?1:0)-(input.left?1:0);if(input.jump)jump(f);if(input.punch)startAttack(f,'punch');if(input.kick)startAttack(f,'kick');if(input.heavy)startAttack(f,'heavy')}else{aiUpdate(dt);if(enemy.aiAction==='approach'&&Math.abs(other.x-f.x)>95)move=Math.sign(other.x-f.x);else if(enemy.aiAction==='retreat')move=-Math.sign(other.x-f.x)}
    if(f.stun<=0&&!f.attack){f.vx+=(move*230*scale-f.vx)*Math.min(1,dt*11);if(move===0)f.vx*=Math.pow(.001,dt);if(move!==0)f.guard=false}else if(f.attack)f.vx*=Math.pow(.06,dt);
    if(!f.grounded){f.vy+=game.height*2.35*dt;f.y+=f.vy*dt;if(f.y>=0){f.y=0;f.vy=0;f.grounded=true}}
    f.x+=f.vx*dt;f.x=clamp(f.x,game.width*.12,game.width*.88);
  }
  function finishRound(){if(game.over)return;game.live=false;const won=player.health>enemy.health;if(won)game.playerWins++;else game.enemyWins++;const complete=game.playerWins>=2||game.enemyWins>=2||game.round>=3;updateHud();if(complete){game.over=true;ui.result.hidden=false;ui.resultTitle.textContent=game.playerWins>game.enemyWins?'VICTORY':'DEFEAT';ui.resultTitle.style.color=game.playerWins>game.enemyWins?'var(--acid)':'var(--red)';ui.resultText.textContent=game.playerWins>game.enemyWins?'The circuit remembers. The crown is yours.':'The circuit never sleeps. Rise and fight again.';return}game.round++;showBanner(`ROUND ${String(game.round).padStart(2,'0')}`,won?'YOU WIN':'CPU WINS');setTimeout(()=>{if(game.over)return;resetFighters();game.live=true;showBanner(`ROUND ${String(game.round).padStart(2,'0')}`,'FIGHT!')},1450)}
  function update(dt){if(game.live){game.time-=dt;if(game.time<=0){game.time=0;finishRound()}if(game.comboTimer>0){game.comboTimer-=dt;if(game.comboTimer<=0)ui.combo.classList.remove('visible')}updateFighter(player,enemy,dt);updateFighter(enemy,player,dt);const gap=enemy.x-player.x,min=game.width*.105;if(gap<min){const overlap=min-gap;player.x-=overlap*.5;enemy.x+=overlap*.5}if(player.health<=0||enemy.health<=0)finishRound();ui.timer.textContent=String(Math.ceil(game.time)).padStart(2,'0');updateHud()}
    for(const p of game.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=280*dt;p.life-=dt}game.particles=game.particles.filter(p=>p.life>0);for(const s of game.sparks){s.x+=s.vx*dt;s.y+=s.vy*dt;s.vy+=440*dt;s.life-=dt}game.sparks=game.sparks.filter(s=>s.life>0);game.shake=Math.max(0,game.shake-dt*28);for(const a of game.ambient){a.y+=a.v*dt;if(a.y>1){a.y=0;a.x=Math.random()}}
  }

  function polygon(points,fill,stroke=null,line=1){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.stroke()}}
  function background(){const w=game.width,h=game.height;const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#111a27');sky.addColorStop(.52,'#24313b');sky.addColorStop(1,'#111822');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
    // distant furnace glow and industrial skyline
    const glow=ctx.createRadialGradient(w*.52,h*.48,5,w*.52,h*.48,w*.52);glow.addColorStop(0,'#dd663326');glow.addColorStop(.38,'#d04e1b14');glow.addColorStop(1,'#f00');ctx.globalAlpha=.35;ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);ctx.globalAlpha=1;
    ctx.fillStyle='#111923';ctx.beginPath();ctx.moveTo(0,h*.57);for(let i=0;i<14;i++){const x=i*w/13;const y=h*(.43+Math.sin(i*12.23)*.1);ctx.lineTo(x,y);ctx.lineTo(x,h*.75)}ctx.lineTo(w,h*.75);ctx.lineTo(0,h*.75);ctx.fill();
    // foundry silhouettes
    for(let i=0;i<9;i++){const x=(i/8)*w;const bw=w*(.055+(i%3)*.016);const top=h*(.31+(i%4)*.045);ctx.fillStyle=i%2?'#17232e':'#192630';ctx.fillRect(x,top,bw,h*.39);ctx.fillStyle='#29343a';ctx.fillRect(x+bw*.22,top-h*.085,bw*.28,h*.09);ctx.fillStyle='#ffae5d';ctx.globalAlpha=.18+(Math.sin(game.accumulator*1.3+i)*.06);for(let r=0;r<3;r++)ctx.fillRect(x+bw*.17+r*bw*.24,top+h*.08,bw*.07,h*.08);ctx.globalAlpha=1}
    // overhead girders
    ctx.fillStyle='#0c131d';ctx.fillRect(0,h*.21,w,h*.018);ctx.fillRect(0,h*.215,w,h*.004);ctx.strokeStyle='#4b4c43';ctx.globalAlpha=.24;ctx.lineWidth=1;for(let i=0;i<11;i++){let x=i*w/10;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h*.215);ctx.stroke()}ctx.globalAlpha=1;
    // drifting embers
    game.ambient.forEach((a,i)=>{ctx.globalAlpha=a.a*(.65+.35*Math.sin(game.accumulator*2+i));ctx.fillStyle=i%3?'#ffc078':'#eaff85';ctx.fillRect(a.x*w,a.y*h,a.s,a.s)});ctx.globalAlpha=1;
    // floor plane
    const floor=game.floor;const fg=ctx.createLinearGradient(0,floor,0,h);fg.addColorStop(0,'#32383a');fg.addColorStop(.14,'#1b2329');fg.addColorStop(1,'#080d15');ctx.fillStyle=fg;ctx.fillRect(0,floor,w,h-floor);ctx.strokeStyle='#c8c0a3';ctx.globalAlpha=.23;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,floor);ctx.lineTo(w,floor);ctx.stroke();ctx.globalAlpha=1;
    // perspective floor markings
    ctx.strokeStyle='#bec0b4';ctx.globalAlpha=.12;for(let i=-6;i<=6;i++){ctx.beginPath();ctx.moveTo(w*.5+i*w*.045,floor);ctx.lineTo(w*.5+i*w*.25,h);ctx.stroke()}for(let j=1;j<6;j++){const y=floor+(h-floor)*j/6;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.globalAlpha=1;
    // worn central insignia
    ctx.save();ctx.translate(w*.5,floor+(h-floor)*.31);ctx.rotate(-.08);ctx.strokeStyle='#e7e1c0';ctx.globalAlpha=.12;ctx.lineWidth=2;ctx.strokeRect(-w*.1,-h*.025,w*.2,h*.05);ctx.font=`900 ${Math.min(w*.045,34)}px Barlow Condensed, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#e6e2d3';ctx.fillText('IRON RIFT',0,0);ctx.restore();ctx.globalAlpha=1;
    // corner hazard lights
    for(const x of [w*.035,w*.965]){ctx.fillStyle='#f0a447';ctx.globalAlpha=.65;ctx.fillRect(x-2,h*.57,4,12);ctx.globalAlpha=.16;ctx.fillRect(x-7,h*.565,14,22)}ctx.globalAlpha=1;
  }
  function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
  function drawFighter(f){const h=game.height,unit=clamp(h*.31,100,205),scale=unit/190,ground=game.floor+f.y;const x=f.x;const time=game.accumulator;ctx.save();ctx.globalAlpha=f.health<=0?.55:1;
    // floor shadow
    ctx.fillStyle='#05080b';ctx.globalAlpha=.52;ctx.beginPath();ctx.ellipse(x,game.floor+4,unit*.34*(f.grounded?1:.66),unit*.075,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=f.health<=0?.55:1;
    ctx.translate(x,ground);ctx.scale(scale*f.face,scale);const airborne=!f.grounded;const bob=airborne?0:Math.sin(time*8+(f.isPlayer?0:2))*(f.attack?0:2);const hurt=f.stun>0;const t=f.attack?clamp(f.attack.t/f.attack.duration,0,1):0;const attackType=f.attack?.type;const strike=attackType==='heavy'?Math.sin(t*Math.PI):attackType==='kick'?Math.sin(t*Math.PI):Math.sin(t*Math.PI);
    ctx.translate(0,bob);
    // trail / impact flare
    if(f.attack&&strike>.5){ctx.globalAlpha=(strike-.5)*.8;ctx.strokeStyle=f.attack.color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,-95,70+strike*20,-.8,.65);ctx.stroke();ctx.globalAlpha=f.health<=0?.55:1}
    // legs
    const gait=f.attack?0:Math.sin(time*8+(f.isPlayer?0:1))*(Math.abs(f.vx)>15?12:2);const crouch=f.guard?13:0;
    ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=f.isPlayer?'#1b2428':'#21191e';ctx.lineWidth=17;ctx.beginPath();ctx.moveTo(-5,-54+crouch);ctx.lineTo(-13+gait*.35,-30);ctx.lineTo(-18+gait*.45,-5);ctx.stroke();ctx.beginPath();ctx.moveTo(5,-54+crouch);ctx.lineTo(17-gait*.4,-29);ctx.lineTo(20-gait*.5,-5);ctx.stroke();
    // boots with colored edge
    ctx.fillStyle=f.isPlayer?'#10191c':'#181419';ctx.beginPath();ctx.roundRect(-31+gait*.45,-10,28,12,4);ctx.fill();ctx.fillStyle=f.isPlayer?'#d8ff43':'#ff584c';ctx.fillRect(-28+gait*.45,-8,19,2);ctx.beginPath();ctx.roundRect(8-gait*.5,-10,28,12,4);ctx.fill();ctx.fillRect(10-gait*.5,-8,19,2);
    // torso, shoulders and collar
    const suit=f.isPlayer?'#252f2e':'#30232a',edge=f.isPlayer?'#d6ff3f':'#ff5949',skin=f.isPlayer?'#c98e69':'#b77f70';
    ctx.fillStyle=suit;ctx.beginPath();ctx.moveTo(-18,-124+crouch);ctx.lineTo(15,-126+crouch);ctx.lineTo(23,-72+crouch);ctx.lineTo(13,-52+crouch);ctx.lineTo(-15,-52+crouch);ctx.lineTo(-24,-75+crouch);ctx.closePath();ctx.fill();
    ctx.fillStyle=f.isPlayer?'#303b37':'#3b292f';ctx.beginPath();ctx.ellipse(0,-114+crouch,22,18,0,0,Math.PI*2);ctx.fill();
    // vest straps and chest graphic
    ctx.strokeStyle=edge;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-15,-119+crouch);ctx.lineTo(-4,-92+crouch);ctx.lineTo(14,-113+crouch);ctx.stroke();ctx.globalAlpha=.65;ctx.fillStyle=edge;ctx.fillRect(-5,-103+crouch,10,3);ctx.globalAlpha=f.health<=0?.55:1;
    // back arm
    ctx.strokeStyle=f.isPlayer?'#202a29':'#251b21';ctx.lineWidth=12;ctx.beginPath();ctx.moveTo(-16,-112+crouch);ctx.lineTo(-29,-92+crouch);ctx.lineTo(-19,-77+crouch);ctx.stroke();ctx.fillStyle=skin;ctx.beginPath();ctx.arc(-19,-77+crouch,8,0,Math.PI*2);ctx.fill();
    // front arm attack poses
    let shoulder={x:15,y:-112+crouch},elbow={x:29,y:-98+crouch},hand={x:21,y:-83+crouch};
    if(f.guard){elbow={x:23,y:-122+crouch};hand={x:13,y:-139+crouch}}
    if(attackType==='punch'){const reach=strike*35;elbow={x:27+reach*.48,y:-108+crouch};hand={x:30+reach,y:-109+crouch}}
    if(attackType==='heavy'){const reach=strike*48;elbow={x:26+reach*.42,y:-91+crouch};hand={x:31+reach,y:-95+crouch}}
    if(attackType==='kick'){elbow={x:24,y:-122+crouch};hand={x:29,y:-131+crouch}}
    ctx.strokeStyle=f.isPlayer?'#202a29':'#251b21';ctx.lineWidth=15;ctx.beginPath();ctx.moveTo(shoulder.x,shoulder.y);ctx.lineTo(elbow.x,elbow.y);ctx.lineTo(hand.x,hand.y);ctx.stroke();ctx.fillStyle=skin;ctx.beginPath();ctx.arc(hand.x,hand.y,9,0,Math.PI*2);ctx.fill();ctx.strokeStyle=edge;ctx.lineWidth=3;ctx.beginPath();ctx.arc(hand.x,hand.y,6,.1,4.7);ctx.stroke();
    // kick limb drawn over body
    if(attackType==='kick'&&strike>.05){const ext=strike*67;ctx.strokeStyle=f.isPlayer?'#1c2827':'#261b21';ctx.lineWidth=17;ctx.beginPath();ctx.moveTo(5,-58+crouch);ctx.lineTo(21+ext*.2,-74+strike*3);ctx.lineTo(24+ext,-81+strike*7);ctx.stroke();ctx.fillStyle=f.isPlayer?'#10191c':'#181419';ctx.beginPath();ctx.roundRect(16+ext,-87+strike*7,33,12,4);ctx.fill();ctx.fillStyle=edge;ctx.fillRect(20+ext,-85+strike*7,20,2)}
    // neck and head
    ctx.fillStyle=skin;ctx.fillRect(-6,-139+crouch,13,20);ctx.fillStyle=f.isPlayer?'#bd8062':'#a66e64';ctx.beginPath();ctx.ellipse(0,-154+crouch,16,20,0,0,Math.PI*2);ctx.fill();
    // hair shape
    ctx.fillStyle=f.isPlayer?'#172326':'#20181e';ctx.beginPath();if(f.isPlayer){ctx.moveTo(-16,-157+crouch);ctx.lineTo(-20,-174+crouch);ctx.lineTo(-6,-169+crouch);ctx.lineTo(2,-181+crouch);ctx.lineTo(8,-168+crouch);ctx.lineTo(18,-171+crouch);ctx.lineTo(15,-151+crouch);ctx.closePath()}else{ctx.moveTo(-17,-157+crouch);ctx.lineTo(-14,-174+crouch);ctx.lineTo(-2,-180+crouch);ctx.lineTo(14,-169+crouch);ctx.lineTo(17,-153+crouch);ctx.closePath()}ctx.fill();
    // face profile details
